 * MARK: QuestionField
 * @description One survey question: native radio/checkbox options (full-width
 *   44px touch targets) for `single`/`multiple`, generated image cards with
 *   radio semantics for `image`, plus an always-present Notes textarea.
 ***/
function QuestionField({ question, selected, notes, missing, onSelect, onNotes, projectId, taskId, imageGenProviderId }) {
  const multi = question.type === 'multiple';
  const inputType = multi ? 'checkbox' : 'radio';
  return (
    <fieldset className="p-4 bg-surface-container border border-border-standard rounded-sm space-y-2.5">
      <legend className="text-sm text-on-surface leading-snug px-1">
        {question.text}
        {question.required && (
          <span className="ml-1.5 text-[10px] font-mono uppercase text-secondary">required</span>
        )}
      </legend>
      {question.type === 'image' ? (
        <ImageOptions
          question={question}
          selected={selected}
          onSelect={onSelect}
          projectId={projectId}
          taskId={taskId}
          imageGenProviderId={imageGenProviderId}
        />
      ) : (
        <div className="flex flex-col gap-1.5">
          {(question.options || []).map((option) => {
            const checked = selected.includes(String(option));
            const inputId = `survey-${question.id}-${encodeURIComponent(String(option))}`;
            return (
              <label
                key={option}
                htmlFor={inputId}
                className={`flex items-center gap-3 w-full min-h-[44px] px-3 py-2 rounded-sm border cursor-pointer text-sm transition-colors ${
                  checked
                    ? 'border-secondary bg-human-fill/50 text-on-surface'
                    : 'border-border-standard text-on-surface hover:border-secondary/60'
                }`}
              >
                <input
                  id={inputId}
                  type={inputType}
                  name={`survey-${question.id}`}
                  value={String(option)}
                  checked={checked}
                  aria-label={`${question.text}: ${option}`}
                  onChange={(e) => onSelect(question.id, String(option), e.target.checked, multi)}
                  className="w-4 h-4 shrink-0 accent-secondary"
                />
                <span className="leading-snug">{option}</span>
              </label>
            );
          })}
        </div>
      )}
      <div className="space-y-1">
        <label
          htmlFor={`survey-notes-${question.id}`}
          className="text-[11px] font-mono text-text-muted"
        >
          Notes (optional)
        </label>
        <textarea
          id={`survey-notes-${question.id}`}
          value={notes}
          aria-label={`Notes for: ${question.text}`}
          onChange={(e) => onNotes(question.id, e.target.value)}
          placeholder="Anything the options did not cover…"
          rows={2}
          className="w-full bg-surface-deep border border-border-standard rounded-sm p-2 text-xs text-on-surface focus:outline-none focus:border-secondary"
        />
      </div>
      {missing && selected.length === 0 && (
        <p className="text-[11px] font-mono text-error">This question still needs an answer.</p>
      )}
    </fieldset>
  );
}

/***
 * MARK: ImageOptions
 * @description One image question's options: ready pictures render as
 *   selectable image cards (radio semantics — pick one favourite), pending
 *   pictures as generating skeletons, and failed or missing pictures as
 *   description rows with an honest notice — answering never blocks on
 *   generation.
 ***/
function ImageOptions({ question, selected, onSelect, projectId, taskId, imageGenProviderId }) {
  const entries = Array.isArray(question.images) ? question.images : [];
  const byOption = new Map();
  for (const entry of entries) {
    if (entry && Number.isInteger(entry.option) && !byOption.has(entry.option)) {
      byOption.set(entry.option, entry);
    }
  }
  const generationOff = imageGenProviderId === 'none' || imageGenProviderId === '';
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2" role="radiogroup" aria-label={question.text}>
      {(question.options || []).map((option, index) => {
        const text = String(option);
        const checked = selected.includes(text);
        const inputId = `survey-${question.id}-img-${index}`;
        const entry = byOption.get(index);
        if (entry?.status === 'ready' && typeof entry.file === 'string' && entry.file) {
          const src = resolveTaskImageUrl({ apiBase: API_BASE, projectId, taskId, src: entry.file });
          return (
            <label
              key={`${text}-${index}`}
              htmlFor={inputId}
              className={`flex flex-col gap-1.5 p-2 rounded-sm border cursor-pointer text-sm transition-colors ${
                checked
                  ? 'border-secondary bg-human-fill/50 text-on-surface'
                  : 'border-border-standard text-on-surface hover:border-secondary/60'
              }`}
            >
              <input
                id={inputId}
                type="radio"
                name={`survey-${question.id}`}
                value={text}
                checked={checked}
                aria-label={`${question.text}: ${text}`}
                onChange={(e) => onSelect(question.id, text, e.target.checked, false)}
                className="sr-only"
              />
              <img
                src={src}
                alt={text}
                loading="lazy"
                className="w-full aspect-video object-cover rounded-sm bg-surface-deep"
              />
              <span className="leading-snug text-xs">{text}</span>
            </label>
          );
        }
        if (entry?.status === 'pending') {
          return (
            <div
              key={`${text}-${index}`}
              role="status"
              aria-label={`${text}: generating illustration`}
              className="flex flex-col gap-1.5 p-2 rounded-sm border border-border-standard text-on-surface"
            >
              <div className="w-full aspect-video rounded-sm bg-surface-deep motion-safe:animate-pulse" />
              <span className="text-[11px] font-mono text-text-muted">Generating illustration…</span>
              <span className="leading-snug text-xs">{text}</span>
            </div>
          );
        }
        return (
          <label
            key={`${text}-${index}`}
            htmlFor={inputId}
            className={`flex items-start gap-3 w-full min-h-[44px] px-3 py-2 rounded-sm border cursor-pointer text-sm transition-colors sm:col-span-2 ${
              checked
                ? 'border-secondary bg-human-fill/50 text-on-surface'
                : 'border-border-standard text-on-surface hover:border-secondary/60'
            }`}
          >
            <input
              id={inputId}
              type="radio"
              name={`survey-${question.id}`}
              value={text}
              checked={checked}
              aria-label={`${question.text}: ${text}`}
              onChange={(e) => onSelect(question.id, text, e.target.checked, false)}
              className="w-4 h-4 shrink-0 mt-1 accent-secondary"
            />
            <span className="leading-snug">
              {text}
              {entry?.status === 'failed' && entry?.error && (
                <span className="block text-[11px] text-text-muted mt-0.5">
                  Illustration unavailable: {entry.error}
                </span>
              )}
              {!entry && !generationOff && (
                <span className="block text-[11px] font-mono text-text-muted mt-0.5">
                  Illustration on its way…
                </span>
              )}
              {!entry && generationOff && (
                <span className="block text-[11px] font-mono text-text-muted mt-0.5">
                  Image generation is off for this survey — pick by description.
                </span>
              )}
            </span>
          </label>

            >
              {notice}
            </div>
          )}

          {status === 'none' && !loadError && (
            <div className="p-4 bg-surface-container border border-border-standard rounded-sm space-y-2">
              <p className="text-xs text-on-surface leading-relaxed">
                The agent did not write any survey questions. If there is genuinely nothing to ask,
                continue — the next stage will proceed without survey input.
              </p>
            </div>
          )}

          {status === 'empty' && (
            <div className="p-4 bg-surface-container border border-border-standard rounded-sm space-y-2">
              <p className="text-xs text-on-surface leading-relaxed">
                The agent considered this task and decided there was nothing worth asking. Continue
                to move on with no answers recorded.
              </p>
            </div>
          )}

          {visibleRounds.map(({ round, visible }) => {
            if (visible.length === 0) return null;
            return (
              <section
                key={`round-${round.round}`}
                aria-label={`Survey round ${round.round}`}
                className="space-y-3"
              >
                {rounds.length > 1 && (
                  <h2 className="text-xs font-bold uppercase tracking-wider text-text-muted font-mono">
                    Round {round.round}
                  </h2>
                )}
                {visible.map((q) => (
                  <QuestionField
                    key={`${round.round}-${q.id}`}
                    question={q}
                    selected={selectedValues(merged, q.id)}
                    notes={merged[q.id]?.notes || ''}
                    missing={missingSet.has(q.id)}
                    onSelect={setSelected}
                    onNotes={setNotes}
                    projectId={projectId}
                    taskId={taskId}
                    imageGenProviderId={imageGenProviderId}
                  />
                ))}
              </section>
            );
          })}

          {hiddenCount > 0 && (
            <p className="text-[11px] font-mono text-text-muted">
              {hiddenCount} follow-up {hiddenCount === 1 ? 'question' : 'questions'} hidden by
              earlier answers.
            </p>
          )}

          {!loadError && (
            <div className="flex flex-col sm:flex-row gap-2 sm:gap-3 pb-6">{actionButtons}</div>
          )}
        </div>
      </div>

      {/* Right column: read-only task context, desktop widths only. Phones
          keep the single-column survey: `hidden md:flex` never renders below
          the `md` (768px) breakpoint. Each column scrolls independently so
          answering never displaces the task description or reports. */}
      <div className="hidden md:flex md:w-1/2 border-l border-border-standard bg-surface overflow-hidden">
        <SurveyTaskPanel
          key={taskId || 'no-task'}
          task={task}
          reports={reports}
          loadingReports={loadingReports}
          loadingTask={loadingTask}
          projectId={projectId}
          taskId={taskId}
          stages={stages}
        />
      </div>
    </div>
  );
}

/***
 * MARK: surveyStatusLine
 * @description One-line survey progress summary for the page header.
 ***/
function surveyStatusLine(survey, totalQuestions) {
  if (!survey) return '';
  const open = (survey.missing || []).length;
  if (survey.status === 'answered')
    return `All required questions answered (${totalQuestions} total).`;
  if (survey.status === 'pending')
    return `${open} required ${open === 1 ? 'question' : 'questions'} still open.`;
  return `${totalQuestions} ${totalQuestions === 1 ? 'question' : 'questions'}.`;
}

